    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def components(I):
    H,W=len(I),len(I[0]); seen=set(); comps=[]
    for i in range(H):
        for j in range(W):
            if I[i][j]==2 and (i,j) not in seen:
                stack=[(i,j)]; comp=set()
                while stack:
                    r,c=stack.pop()
                    if (r,c) in comp: continue
                    comp.add((r,c)); seen.add((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c+dc
                            if 0<=nr<H and 0<=nc<W and I[nr][nc]==2 and (nr,nc) not in comp:
                                stack.append((nr,nc))
                comps.append(comp)
    return comps
def norm(s): 
    r0=min(r for r,_ in s); c0=min(c for _,c in s)
    return tuple(sorted((r-r0,c-c0) for r,c in s)),r0,c0
