    # non-bg cells
    cells=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=bg]
    if not cells: return [r[:] for r in g]
    # connected components (4-conn) of non-bg
    seen=set();comps=[]
    for y,x,v in cells:
        if (y,x) in seen: continue
        st=[(y,x)];seen.add((y,x));comp=[]
        while st:
            cy,cx=st.pop();comp.append((cy,cx,g[cy][cx]))
            for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                n=(cy+dy,cx+dx)
                if 0<=n[0]<H and 0<=n[1]<W and g[n[0]][n[1]]!=bg and n not in seen:
                    seen.add(n);st.append(n)
        comps.append(comp)
    comps.sort(key=len,reverse=True)
    comp=comps[0]
    ys=[p[0] for p in comp];xs=[p[1] for p in comp]
    rh,rw=max(ys)-min(ys)+1,max(xs)-min(xs)+1
    ay,ax=(rh-1)//2,(rw-1)//2
    pat=[[None]*rw for _ in range(rh)]
    for y,x,v in comp:
        pat[y-min(ys)][x-min(xs)]=v
    noise=[(y,x,v) for y,x,v in cells if (y,x) not in set(p[0] for p in comp)]
    res=[r[:] for r in g]
    for y,x,_ in noise:
        for i in range(rh):
            for j in range(rw):
                if pat[i][j] is not None and 0<=y+i<H and 0<=x+j<W:
                    res[y+i][x+j]=pat[i][j]
    return res
