import os,glob,re
def load():
    G={}
    for p in sorted(glob.glob(os.path.normpath(os.environ['RLM_SESSION_DIR'])+'/../../sessions/*.jsonl')):
        t=open(p,errors='ignore').read().replace('\\n','\n')
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
            k,h,w=m[1],int(m[2]),int(m[3])
            rows=[r.split() for r in t[m.end():].split('\n')[:h]]
            if all(len(r)==w and all(x.isdigit() for x in r) for r in rows) and k not in G:
                G[k]=[[int(x) for x in r] for r in rows]
    return G
